from pathlib import Path
import runpy
shared=runpy.run_path(str(Path(__file__).with_name('build-pages.py')))
page,svg,SITE=shared['page'],shared['svg'],shared['SITE']

def conductor(x,y,kind):
    dot='' if kind=='cross' else '<circle class="current-dot" r="4" fill="#4a3424"/>'
    cross='<path class="current-cross" d="M-4-4L4 4M4-4L-4 4" fill="none" stroke="#4a3424" stroke-width="2.3" stroke-linecap="round"/>'
    if kind=='dot': cross=cross.replace('class="current-cross"','class="current-cross" opacity="0"')
    if kind=='cross': dot='<circle class="current-dot" r="4" fill="#4a3424" opacity="0"/>'
    return f'<g transform="translate({x} {y})"><circle r="12" fill="url(#conductor-copper)" stroke="#ad8055" stroke-width="1.2"/>{dot}{cross}</g>'

wire=svg('''<defs><radialGradient id="wire-copper" cx="35%" cy="25%"><stop stop-color="#f4d3a0"/><stop offset=".6" stop-color="#d3a26b"/><stop offset="1" stop-color="#a76d40"/></radialGradient><marker id="wire-arrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6Z" fill="#45775d"/></marker></defs><g fill="none" stroke="#8ca994"><circle cx="115" cy="107" r="72" opacity=".22"/><circle cx="115" cy="107" r="54" opacity=".5"/><circle cx="115" cy="107" r="36" opacity=".8"/><circle cx="325" cy="107" r="72" opacity=".22"/><circle cx="325" cy="107" r="54" opacity=".5"/><circle cx="325" cy="107" r="36" opacity=".8"/></g><path d="M169 107A54 54 0 0 0 115 53M271 107A54 54 0 0 1 325 53" fill="none" stroke="#45775d" stroke-width="2" marker-end="url(#wire-arrow)"/><g fill="url(#wire-copper)" stroke="#b6804f"><circle cx="115" cy="107" r="17"/><circle cx="325" cy="107" r="17"/></g><circle cx="115" cy="107" r="4.5" fill="#4a3424"/><path d="M319 101L331 113M331 101L319 113" stroke="#4a3424" stroke-width="2.6" stroke-linecap="round"/><g font-family="system-ui,sans-serif" text-anchor="middle"><text x="115" y="210" fill="#314f3f" font-size="14" font-weight="600">Strom zu dir</text><text x="325" y="210" fill="#314f3f" font-size="14" font-weight="600">Strom von dir weg</text><text x="115" y="232" fill="#788978" font-size="11">Feld gegen den Uhrzeigersinn</text><text x="325" y="232" fill="#788978" font-size="11">Feld im Uhrzeigersinn</text></g>''','0 0 440 255','Drahtquerschnitte: Beim Punkt fließt Strom aus dem Bild, das Feld dreht gegen den Uhrzeigersinn. Beim Kreuz fließt er hinein, das Feld dreht im Uhrzeigersinn.')

cross=svg('''<defs><linearGradient id="conductor-copper" x2="1" y2="1"><stop stop-color="#eed0a4"/><stop offset=".6" stop-color="#c99760"/><stop offset="1" stop-color="#a96c3d"/></linearGradient><linearGradient id="core-steel" x2="0" y2="1"><stop stop-color="#e3e9e2"/><stop offset=".5" stop-color="#a8b7a8"/><stop offset="1" stop-color="#d4ddd0"/></linearGradient><marker id="field-arrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6Z" fill="#3c7858"/></marker></defs><rect x="128" y="119" width="384" height="162" rx="18" fill="#e8eee1" stroke="#cbd7c6" stroke-dasharray="3 5"/><rect id="svg-core" x="122" y="157" width="396" height="86" rx="8" fill="url(#core-steel)" opacity="0"/><g id="field-lines" fill="none" stroke="#4c8762" stroke-width="1.7"><path d="M133 200H507C618 200 606 48 454 48H186C34 48 22 200 133 200Z" opacity=".38"/><path d="M133 200H507C596 200 571 79 449 79H191C69 79 44 200 133 200Z" opacity=".6"/><path d="M133 200H507C618 200 606 352 454 352H186C34 352 22 200 133 200Z" opacity=".38"/><path d="M133 200H507C596 200 571 321 449 321H191C69 321 44 200 133 200Z" opacity=".6"/><path d="M166 176H474M166 200H474M166 224H474" marker-end="url(#field-arrow)"/><path d="M355 79H292M355 321H292" marker-end="url(#field-arrow)"/></g><g id="cross-top">'''+''.join(conductor(x,119,'dot') for x in range(152,500,48))+'''</g><g id="cross-bottom">'''+''.join(conductor(x,281,'cross') for x in range(152,500,48))+'''</g><g font-family="system-ui,sans-serif" text-anchor="middle"><circle cx="75" cy="200" r="22" fill="#edf2f3" stroke="#d7e1df"/><circle cx="565" cy="200" r="22" fill="#f4e9df" stroke="#e5d2c1"/><text id="pole-left" x="75" y="207" fill="#577b88" font-size="20" font-weight="600">S</text><text id="pole-right" x="565" y="207" fill="#a06841" font-size="20" font-weight="600">N</text><text x="320" y="388" fill="#73866f" font-size="12">Schnitt längs durch die Spule · Feldlinien geschlossen</text></g>''','0 0 640 410','Spule im Schnitt: oben tritt Strom aus dem Bild, unten hinein. Das Magnetfeld zeigt innen nach rechts zum Nordpol, außen zurück zum Südpol.')

# Small, exact domain arrows, kept separate from the photorealistic illustrations.
domain_tiles=''
for tile_x,angles in [(25,[35,-70,135,85,-20,-145]),(245,[0,0,0,0,0,0])]:
    domain_tiles+=f'<rect x="{tile_x}" y="27" width="170" height="150" rx="14" fill="#f8faf5" stroke="#d5dfce"/>'
    for index,angle in enumerate(angles):
        x=tile_x+39+(index%3)*46;y=72+(index//3)*60
